fn solve(n: i8) -> Vec<i8> {
    // We only expect 1 ≤ n ≤ 127, but handle out‐of‐range gracefully
    if n < 1 {
        return vec![-1];
    }

    match n % 3 {
        0 => {
            // n divisible by 3
            let a = n / 3;
            vec![a, 0, 0]
        }
        1 => {
            // n ≡ 1 (mod 3)
            if n < 7 {
                vec![-1]
            } else {
                let a = (n - 7) / 3;
                vec![a, 0, 1]
            }
        }
        2 => {
            // n ≡ 2 (mod 3)
            if n < 5 {
                vec![-1]
            } else {
                let a = (n - 5) / 3;
                vec![a, 1, 0]
            }
        }
        // For completeness; modulo 3 on nonnegative n can't produce other values
        _ => unreachable!(),
    }
}

